function readJson(key,fallback){ try{return JSON.parse(localStorage.getItem(key)||"null")||fallback;}catch{return fallback;} }
function normalizeWorkflow(value={}){ const confirmed=value.confirmed||{}; return {...value,confirmed:{production:Boolean(confirmed.production),administration:Boolean(confirmed.administration),procurement:Boolean(confirmed.procurement)},status:["draft","submitted","approved"].includes(value.status)?value.status:"draft",events:Array.isArray(value.events)?value.events:[]}; }
