function employeeValue(item,field,index,saved){ const value=Number(saved?.values?.[`dw.${item.id}.${field}.${index}`]); return Number.isFinite(value)?value:n(item[field]); }
function employeeFor(index){ const saved=readJson(STORAGE.employee,{values:{}}); const out={direct:0,indirect:0,white:0,shared:0}; for(const department of EMPLOYEE_ATTENDANCE_DATA.factories.dw.departments){ for(const item of department.rows){ for(const field of EMPLOYEE_ATTENDANCE_DATA.fields) out[field]+=employeeValue(item,field,index,saved); } } return out; }
function serviceFor(index){ const saved=readJson(STORAGE.attendance,{values:{}}); const unit=ADMIN_ATTENDANCE_DATA.groups.dw.units.find((item)=>item.id==="dw"); const out={}; for(const [key] of ADMIN_ATTENDANCE_DATA.categories){ if(["direct","indirect","whiteCollar"].includes(key)) continue; const raw=Number(saved?.values?.[`dw.${key}.${index}`]); out[key]=Number.isFinite(raw)?raw:n(unit.entries?.[key]?.[index]); } return out; }
function r2EmployeeFor(index){ const unit=ADMIN_ATTENDANCE_DATA.groups.dw.units.find((item)=>item.id==="dw"); return {direct:n(unit.entries.direct[index]),indirect:n(unit.entries.indirect[index]),white:n(unit.entries.whiteCollar[index]),shared:0}; }
function r2ServiceFor(index){ const unit=ADMIN_ATTENDANCE_DATA.groups.dw.units.find((item)=>item.id==="dw"); return Object.fromEntries(ADMIN_ATTENDANCE_DATA.categories.filter(([key])=>!["direct","indirect","whiteCollar"].includes(key)).map(([key])=>[key,n(unit.entries?.[key]?.[index])])); }
