function pricesFor(index){ const saved=readJson(STORAGE.procurement,{checks:{}}); const result={}; for(const [categoryId,lines] of Object.entries(DW_PROCUREMENT_PRICE_LINES)){ for(const line of lines){ const record=saved?.checks?.[`${categoryId}.${line.id}.${index}`]; if(Number.isFinite(Number(record?.value))) result[line.id]=Number(record.value); } } return result; }
function snapshot(index){ return calculateDwHeadcountBudget({employee:employeeFor(index),service:serviceFor(index),monthIndex:index,procurementPrices:pricesFor(index),adminParameters:rulesFor(index)}); }
function amountTry(id,row){ return n({canteen:row.amounts.canteenTry,shuttle:row.amounts.shuttleTry,uniforms:row.amounts.uniformsTry}[id]); }
function latestKEur(id,index){ if(index<ACTUAL_CUTOFF) return actualKEur(id,index); const row=snapshot(index); return n({canteen:row.amounts.canteenTry,shuttle:row.amounts.shuttleTry,uniforms:row.amounts.uniformsTry}[id]) / n(ADMIN_BUDGET_DATA.eurTry) / 1000; }
function total(id,from,to,fn){ return sum(Array.from({length:to-from+1},(_,offset)=>fn(id,from+offset))); }
function fullLatest(id){ return total(id,0,11,latestKEur); }
function fullR2(id){ return total(id,0,11,r2KEur); }
function bridgeFor(id,index){ const divisor=n(ADMIN_BUDGET_DATA.eurTry)*1000; const baseline=calculateDwHeadcountBudget({employee:r2EmployeeFor(index),service:r2ServiceFor(index),monthIndex:index}); const people=calculateDwHeadcountBudget({employee:employeeFor(index),service:serviceFor(index),monthIndex:index}); const priced=calculateDwHeadcountBudget({employee:employeeFor(index),service:serviceFor(index),monthIndex:index,procurementPrices:pricesFor(index)}); const parameterized=snapshot(index); const result={people:(amountTry(id,people)-amountTry(id,baseline))/divisor,price:(amountTry(id,priced)-amountTry(id,people))/divisor,parameter:(amountTry(id,parameterized)-amountTry(id,priced))/divisor}; result.other=latestKEur(id,index)-r2KEur(id,index)-result.people-result.price-result.parameter; return result; }
function annualBridge(id){ return [7,8,9,10,11].reduce((out,index)=>{ const item=bridgeFor(id,index); for(const key of Object.keys(out)) out[key]+=item[key]; return out; },{people:0,price:0,parameter:0,other:0}); }
function hasSaved(prefix,index){ const records={production:readJson(STORAGE.employee,{values:{}}).values,administration:readJson(STORAGE.attendance,{values:{}}).values,procurement:readJson(STORAGE.procurement,{checks:{}}).checks}; return Object.keys(records[prefix] || {}).some((key)=>key.endsWith(`.${index}`)); }
function confirmationStatus(key){ return state.workflow.confirmed[key] ? "confirmed" : "pending"; }
function allConfirmed(){ return ["production","administration","procurement"].every((key)=>state.workflow.confirmed[key]); }
function forecastStatus(){ if(state.workflow.status==="approved") return "approved"; if(state.workflow.status==="submitted") return "submitted"; return allConfirmed()?"ready":"draft"; }
function statusText(status){ return t(status==="approved"?"approvedForecast":status==="submitted"?"submitted":status==="ready"?"ready":"draft"); }
function statusClass(status){ return status==="approved"?"approved":status==="submitted"||status==="ready"?"draft":"pending"; }
