function driverRows(id,row){ const employee=row.employee,service=row.service; if(id==="canteen") return [[t("directEmployee"),employee.direct,"production",t("employeeForecastSource")],[t("indirectEmployee"),employee.indirect,"production",t("employeeForecastSource")],[t("whiteCollar"),employee.white,"production",t("employeeForecastSource")],[t("serviceHeadcount"),sum(Object.values(service)),"administration",t("adminAttendanceSource")],[t("overtimeRate"),`${money(row.parameters.overtimeRate*100)}%`,"administration",t("sharedParameterSource")],[t("workdays"),row.workdays,"system",t("r2CalendarSource")],[t("mealUnitPrice"),`${money(row.mealPrice)} TRY`,"procurement",t("contractInvoiceSource")]]; if(id==="shuttle") return [[t("eligibleRiders"),money(row.shuttleHeadcount),"system",t("eligibleRidersSource")],[t("routeDailyPrice"),`${money(row.shuttleRouteDailyPrice)} TRY`,"procurement",t("contractInvoiceSource")],[t("vehicleCapacity"),row.parameters.shuttleCapacity,"administration",t("shuttleRuleSource")],[t("targetOccupancy"),`${money(row.parameters.shuttleTargetOccupancy*100)}%`,"administration",t("shuttleRuleSource")],[t("roundTripFactor"),row.parameters.shuttleRoundTripFactor,"administration",t("shuttleRuleSource")],[t("workdays"),row.workdays,"system",t("r2CalendarSource")]]; return [["BC",money(row.uniform.blue),"production",t("uniformBlueSource")],["WC",money(row.uniform.white),"production",t("uniformWhiteSource")],["SUB",money(row.uniform.sub),"administration",t("uniformSubSource")],[t("sharedPersonnel"),t("pending"),"administration",t("shared")],[t("annualAllocation"),`÷ ${row.parameters.uniformAllocationDivisor}`,"administration",t("r2RuleSource")],[t("inventoryDeduction"),t("pending"),"administration",t("inventory")]]; }
