function editableDriverPanel(id,row,index){
  if(accessRole!=="adminThree") return "";
  const fields=editableDriverDefinitions(id,row).map((item)=>`<label><span>${escapeHtml(item.label)}</span><div><input type="number" value="${escapeHtml(String(Number(item.value.toFixed(4))))}" min="${item.min}" ${item.max==null?"":`max="${item.max}"`} step="${item.step}" data-driver-input="${item.store}|${id}|${item.key}|${index}|${item.scale}" aria-label="${escapeHtml(`${item.label} · ${yearMonthLabel(index)}`)}"/><small>${escapeHtml(item.unit)}</small></div></label>`).join("");
  return `<section class="editable-driver-panel"><header><div><h3>${escapeHtml(t("editableInputs"))}</h3><p>${escapeHtml(t("editableInputsHint"))}</p></div><button type="button" class="button primary" data-save-drivers>${escapeHtml(t("saveInputs"))}</button></header><div class="editable-driver-grid">${fields}</div></section>`;
}
function saveEditableDrivers(){
  if(accessRole!=="adminThree") return;
  const workflowFrom=workflowStage();
  const rules=readJson(STORAGE.rules,{draft:{},saved:{},origins:{}});
  const procurement=readJson(STORAGE.procurement,{checks:{},drafts:{}});
  rules.draft=rules.draft||{}; rules.saved=rules.saved||{}; rules.origins=rules.origins||{};
  procurement.checks=procurement.checks||{}; procurement.drafts=procurement.drafts||{};
  let changed=0;
  for(const input of document.querySelectorAll("[data-driver-input]")){
    const [storeName,categoryId,key,indexText,scaleText]=input.dataset.driverInput.split("|");
    const index=Number(indexText),scale=Number(scaleText)||1,displayed=Number(input.value);
    if(!Number.isFinite(displayed)||!Number.isInteger(index)||index<7||index>11) continue;
    const value=Math.max(0,displayed/scale);
    if(storeName==="rules"&&key in DW_ADMIN_PARAMETER_DEFAULTS){
      const savedForMonth=rules.saved[String(index)]||rules.draft[String(index)]||{};
      const previous=Number.isFinite(Number(savedForMonth[key]))?Number(savedForMonth[key]):Number(DW_ADMIN_PARAMETER_DEFAULTS[key]);
      if(Math.abs(previous-value)<1e-9) continue;
      rules.draft[String(index)]={...DW_ADMIN_PARAMETER_DEFAULTS,...(rules.draft[String(index)]||rules.saved[String(index)]||{}),[key]:value};
      rules.saved[String(index)]={...DW_ADMIN_PARAMETER_DEFAULTS,...(rules.saved[String(index)]||rules.draft[String(index)]||{}),[key]:value};
      rules.origins[`${index}|${key}`]=categoryId;
      changed+=1;
    }
    if(storeName==="procurement"){
      const storageKey=`${categoryId}.${key}.${index}`;
      const savedValue=Number(procurement.checks[storageKey]?.value);
      const line=(DW_PROCUREMENT_PRICE_LINES[categoryId]||[]).find((item)=>item.id===key);
      const baseline=Array.isArray(line?.baseline)?Number(line.baseline[index]):Number(line?.baseline);
      const previous=Number.isFinite(savedValue)?savedValue:baseline;
      if(Number.isFinite(previous)&&Math.abs(previous-value)<1e-9) continue;
      procurement.checks[storageKey]={value,reason:t("editableInputs"),actor:"adminThree",timestamp:new Date().toISOString()};
      changed+=1;
    }
  }
  if(!changed) return;
  localStorage.setItem(STORAGE.rules,JSON.stringify(rules));
  localStorage.setItem(STORAGE.procurement,JSON.stringify(procurement));
  if(workflowFrom!=="draft"){
    state.workflow.status="draft";
    state.workflow.confirmed={production:false,administration:false,procurement:false};
  }
  addWorkflowEvent("saveDrivers",workflowFrom,"draft",{account:state.account,changes:changed});
  saveWorkflow();
  render();
  toast(t(workflowFrom==="draft"?"inputsSaved":"savedReset"));
}
function formula(id){ const texts={canteen:{zh:"（用餐适用人数 + 加班人数）× 工作日 × 餐费单价；已取消周日加班",en:"(Eligible meal headcount + overtime) × workdays × meal price; Sunday overtime removed",tr:"(Uygun yemek kişi sayısı + fazla mesai) × iş günü × yemek fiyatı; Pazar mesaisi kaldırıldı"},shuttle:{zh:"乘车适用人数 × 工作日 × [线路日价 ÷（座位数 × 上座率）× 往返系数]",en:"Eligible riders × workdays × [route daily price ÷ (capacity × occupancy) × round trip]",tr:"Uygun yolcu × iş günü × [hat günlük fiyatı ÷ (kapasite × doluluk) × gidiş-dönüş]"},uniforms:{zh:"BC、WC、SUB发放标准 × 单价 + 固定物品；年度金额 ÷ 12",en:"BC, WC and SUB issue standards × prices + fixed items; annual amount ÷ 12",tr:"BC, WC ve SUB dağıtım standardı × fiyat + sabit kalemler; yıllık tutar ÷ 12"}}; return texts[id][state.language]; }
function toast(message){ els.toast.textContent=message; els.toast.classList.add("show"); window.setTimeout(()=>els.toast.classList.remove("show"),2400); }
function delta(value){ return `${value>=0?"+":""}${keur(value)}`; }
function deltaClass(value){ return value>.005?"variance-up":value<-.005?"variance-down":""; }
function rollingVarianceFor(id,vintage){ return actualKEur(id,vintage.actualMonthIndex)-n(vintage.forecast[id]); }
function rollingVarianceTooltip(id,vintage){ const forecast=n(vintage.forecast[id]),actual=actualKEur(id,vintage.actualMonthIndex); return t("varianceCellTip").replace("{version}",vintage.version).replace("{month}",monthLabel(vintage.actualMonthIndex)).replace("{account}",accountName(id)).replace("{forecast}",keur(forecast)).replace("{actual}",keur(actual)).replace("{variance}",delta(actual-forecast)); }
function hideVarianceHover(){ els.varianceHover.hidden=true; }
function showVarianceHover(target){ els.varianceHover.textContent=target.dataset.varianceTip; els.varianceHover.hidden=false; const rect=target.getBoundingClientRect(),gap=8,margin=12,width=els.varianceHover.offsetWidth,height=els.varianceHover.offsetHeight; const left=Math.min(Math.max(rect.left+rect.width/2-width/2,margin),window.innerWidth-width-margin); let top=rect.bottom+gap; if(top+height>window.innerHeight-margin) top=rect.top-height-gap; els.varianceHover.style.left=`${left}px`; els.varianceHover.style.top=`${Math.max(margin,top)}px`; target.setAttribute("aria-describedby","varianceHover"); }

function renderShell(){
  const s=forecastStatus();
  document.documentElement.lang=state.language==="zh"?"zh-CN":state.language;
  document.title=`${state.version==="r2"?t("r2"):t("current")} · DW`;
  els.title.textContent=t("title");
  els.subtitle.textContent=t("subtitle");
  els.languageLabel.textContent=t("language");
  els.versionLabel.textContent=t("version");
  els.language.setAttribute("aria-label",t("language"));
  els.version.setAttribute("aria-label",t("version"));
  els.language.value=state.language;
  els.version.options[0].textContent=t("r2");
  els.version.options[1].textContent=t("current");
  els.version.value=state.version;
  els.versionStatus.className=`status ${state.version==="r2"?"approved":statusClass(s)}`;
  els.versionStatus.textContent=state.version==="r2"?t("lockedBaseline"):statusText(s);
  els.back.textContent=t("backMfg");
  els.back.title=t("backMfg");
  els.back.setAttribute("aria-label",t("backMfg"));
  const context=[[t("company"),contextValue("company")],[t("costCenter"),contextValue("costCenter")],[t("fiscal"),"2026"],[t("currency"),contextValue("currency")],[t("actualCutoff"),contextValue("actualCutoff")],[t("source"),contextValue("source")]];
  els.context.setAttribute("aria-label",t("modelInfo"));
  els.context.innerHTML=`<details class="model-info"><summary><span>${escapeHtml(t("modelInfo"))}</span><small>${escapeHtml(t("modelInfoHint"))}</small><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 10 4 4 4-4"/></svg></summary><div class="context-grid">${context.map(([key,value])=>`<div><span>${escapeHtml(key)}</span><b>${escapeHtml(value)}</b></div>`).join("")}</div></details>`;
  const showOverview=state.view==="forecast";
  els.cards.hidden=!showOverview;
  if(showOverview){ renderSummary(); renderActualVarianceMatrix(); }
  else { els.monthlyVariance.hidden=true; els.monthlyVariance.replaceChildren(); els.cards.replaceChildren(); }
  const tabs=VIEW_IDS.map((id)=>[id,t(id)]);
  els.rail.setAttribute("aria-label",t("navigation"));
  els.rail.innerHTML=tabs.map(([id,label])=>{ const disabled=state.version==="r2"&&id!=="forecast"; return `<button class="${state.view===id?"active":""}" data-view="${id}" title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}" aria-current="${state.view===id?"page":"false"}" ${disabled?"disabled":""}>${ICONS[id]}<span>${escapeHtml(label)}</span></button>`; }).join("");
  els.tabs.innerHTML=tabs.map(([id,label])=>{ const disabled=state.version==="r2"&&id!=="forecast"; return `<button class="${state.view===id?"active":""}" data-view="${id}" aria-current="${state.view===id?"page":"false"}" ${disabled?"disabled":""}>${escapeHtml(label)}</button>`; }).join("");
}
function renderSummary(){
  const r2=sum(ACCOUNT_IDS.map(fullR2));
  els.cards.setAttribute("aria-label",t("varianceOverview"));
  if(state.version==="r2"){
    const first=sum(ACCOUNT_IDS.map((id)=>total(id,0,6,r2KEur)));
    const future=sum(ACCOUNT_IDS.map((id)=>total(id,7,11,r2KEur)));
    els.cards.className="baseline-stage";
    els.cards.innerHTML=`<section class="baseline-sheet"><header class="stage-head"><div><h2>${escapeHtml(t("baselineTitle"))}</h2><span class="status approved">${escapeHtml(t("lockedBaseline"))}</span></div><span class="unit-note">${escapeHtml(t("unitNote"))}</span></header><div class="baseline-readings"><article tabindex="0" data-tooltip="${escapeHtml(t("baselineTooltip"))}"><span>${escapeHtml(t("r2Total"))}</span><strong>${keur(r2)}</strong></article><article><span>${escapeHtml(t("r2FirstPeriod"))}</span><strong>${keur(first)}</strong></article><article><span>${escapeHtml(t("r2Future"))}</span><strong>${keur(future)}</strong></article></div><div class="baseline-accounts">${ACCOUNT_IDS.map((id)=>`<div><span>${escapeHtml(accountName(id))}</span><strong>${keur(fullR2(id))}</strong></div>`).join("")}</div></section>`;
    return;
  }
  const actual=sum(ACCOUNT_IDS.map((id)=>total(id,0,6,actualKEur)));
  const future=sum(ACCOUNT_IDS.map((id)=>total(id,7,11,latestKEur)));
  const latest=actual+future;
  const variance=latest-r2;
  const variancePct=r2?variance/r2*100:0;
  const impacts=ACCOUNT_IDS.map((id)=>({id,value:fullLatest(id)-fullR2(id)})).sort((a,b)=>Math.abs(b.value)-Math.abs(a.value));
  els.cards.className="variance-stage";
  els.cards.innerHTML=`<section class="control-room"><header class="stage-head"><h2>${escapeHtml(t("varianceOverview"))}</h2><span class="unit-note">${escapeHtml(t("unitNote"))}</span></header><div class="control-layout"><div class="control-main"><div class="baseline-track"><div class="track-field" aria-hidden="true"></div><div class="track-end track-start" tabindex="0" data-tooltip="${escapeHtml(t("baselineTooltip"))}"><span>${escapeHtml(t("r2Baseline"))}</span><strong>${keur(r2)}</strong></div><div class="variance-marker ${deltaClass(variance)}" tabindex="0" data-tooltip="${escapeHtml(t("varianceTooltip"))}"><span>${escapeHtml(t("fullVariance"))}</span><strong>${delta(variance)}</strong><small>${variancePct>=0?"+":""}${money(variancePct)}%</small></div><div class="track-end track-finish" tabindex="0" data-tooltip="${escapeHtml(t("latestTooltip"))}"><span>${escapeHtml(t("latestForecast"))}</span><strong>${keur(latest)}</strong></div></div><div class="period-pair"><article tabindex="0" data-tooltip="${escapeHtml(t("actualTooltip"))}"><span>${escapeHtml(t("actualTotal"))}</span><strong>${keur(actual)}</strong></article><article tabindex="0" data-tooltip="${escapeHtml(t("forecastTooltip"))}"><span>${escapeHtml(t("futureForecast"))}</span><strong>${keur(future)}</strong></article></div></div><aside class="impact-queue"><h3>${escapeHtml(t("impactRanking"))}</h3>${impacts.map((item,index)=>{ const tip=`${accountName(item.id)}: ${t("impactTooltip")}`; return `<button type="button" class="impact-row ${deltaClass(item.value)}" data-impact-account="${item.id}" data-tooltip="${escapeHtml(tip)}" aria-label="${escapeHtml(tip)}"><span class="impact-rank">${index+1}</span><b>${escapeHtml(accountName(item.id))}</b><strong>${delta(item.value)}</strong><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg></button>`; }).join("")}</aside></div></section>`;
}
function renderActualVarianceMatrix(){
  els.monthlyVariance.hidden=state.version==="r2"||state.view!=="forecast";
  if(els.monthlyVariance.hidden) return;
  const rowTotal=(id)=>sum(DW_ROLLING_VINTAGES.map((vintage)=>rollingVarianceFor(id,vintage)));
  const vintageTotal=(vintage)=>sum(ACCOUNT_IDS.map((id)=>rollingVarianceFor(id,vintage)));
  const accountRows=ACCOUNT_IDS.map((id)=>`<tr><td><b>${escapeHtml(accountName(id))}</b></td>${DW_ROLLING_VINTAGES.map((vintage)=>{ const value=rollingVarianceFor(id,vintage),tip=rollingVarianceTooltip(id,vintage); return `<td><span tabindex="0" class="variance-cell ${deltaClass(value)}" data-variance-tip="${escapeHtml(tip)}" aria-label="${escapeHtml(tip)}">${delta(value)}</span></td>`; }).join("")}<td class="variance-cumulative ${deltaClass(rowTotal(id))}">${delta(rowTotal(id))}</td></tr>`).join("");
  const totalRow=`<tr class="variance-total"><td><b>${escapeHtml(t("total"))}</b></td>${DW_ROLLING_VINTAGES.map((vintage)=>{ const value=vintageTotal(vintage); return `<td class="${deltaClass(value)}">${delta(value)}</td>`; }).join("")}<td class="variance-cumulative ${deltaClass(sum(ACCOUNT_IDS.map(rowTotal)))}">${delta(sum(ACCOUNT_IDS.map(rowTotal)))}</td></tr>`;
  els.monthlyVariance.innerHTML=`<section class="actual-variance-panel"><header><div><h2>${escapeHtml(t("actualVarianceTitle"))}</h2><p>${escapeHtml(t("actualVarianceHint"))}</p></div><div class="variance-legend"><span class="variance-down">−</span><small>${escapeHtml(t("favorable"))}</small><span class="variance-up">+</span><small>${escapeHtml(t("adverse"))}</small></div></header><div class="actual-variance-scroll"><table class="actual-variance-table" aria-label="${escapeHtml(t("actualVarianceTitle"))}"><colgroup><col class="account-col"/><col span="5" class="value-col"/></colgroup><thead><tr><th>${escapeHtml(t("account"))}</th>${DW_ROLLING_VINTAGES.map((vintage)=>`<th>${escapeHtml(vintage.version)} · ${escapeHtml(monthLabel(vintage.actualMonthIndex))}</th>`).join("")}<th>${escapeHtml(t("total"))}</th></tr></thead><tbody>${accountRows}${totalRow}</tbody></table></div></section>`;
}
function accountNav(){ return `<aside class="account-nav"><h3>${t("account")}</h3>${ACCOUNT_IDS.map((id)=>`<button class="${state.account===id?"active":""}" data-account="${id}"><b>${accountName(id)}</b><small>${accountCode(id)}</small></button>`).join("")}</aside>`; }
function renderR2Baseline(){ els.view.innerHTML=`<section class="panel"><header class="panel-head"><div><h2>${t("r2")}</h2></div><div class="panel-head-actions">${infoTip(t("baselineHint"))}<span class="status approved">${t("lockedBaseline")}</span></div></header><div class="forecast-grid"><table aria-label="${escapeHtml(t("baselineTitle"))}"><thead><tr><th>${t("account")}</th>${Array.from({length:12},(_,index)=>`<th>${monthLabel(index)}</th>`).join("")}<th class="total-column">${t("r2Total")}</th></tr></thead><tbody>${ACCOUNT_IDS.map((id)=>`<tr><td class="account-name"><b>${accountName(id)}</b><small>${accountCode(id)}</small></td>${Array.from({length:12},(_,index)=>`<td>${keur(r2KEur(id,index))}</td>`).join("")}<td class="total-column">${keur(fullR2(id))}</td></tr>`).join("")}</tbody></table></div></section>`; }
function renderForecast(){ els.view.innerHTML=`<section class="panel"><header class="panel-head"><h2>${t("rollingTitle")}</h2><div class="panel-head-actions">${infoTip(t("rollingHint"))}<span class="status actual">${t("actualLocked")}</span></div></header><div class="forecast-grid"><table class="forecast-ledger" aria-label="${escapeHtml(t("rollingTitle"))}"><colgroup><col class="account-col"/><col span="11" class="value-col"/></colgroup><thead><tr><th>${t("account")}</th><th class="month-actual">${t("julyR2")}</th><th class="month-actual">${t("julyPrevious")}</th><th class="month-actual">${t("julyActual")}</th><th class="month-actual">${t("julyVar")}</th>${[7,8,9,10,11].map((index)=>`<th class="month-forecast">${monthLabel(index)}</th>`).join("")}<th class="total-column">${t("fullLatest")}</th><th class="total-column">${t("fullVariance")}</th></tr></thead><tbody>${ACCOUNT_IDS.map((id)=>{ const julyActual=actualKEur(id,6),r2=r2KEur(id,6),previous=previousKEur(id,6),annual=fullLatest(id),annualVar=annual-fullR2(id); return `<tr><td class="account-name"><b>${accountName(id)}</b><small>${accountCode(id)}</small></td><td class="month-actual">${keur(r2)}</td><td class="month-actual">${keur(previous)}</td><td class="month-actual actual-lock">${keur(julyActual)}</td><td class="month-actual ${deltaClass(julyActual-r2)}">${delta(julyActual-r2)}</td>${[7,8,9,10,11].map((index)=>`<td class="month-forecast">${keur(latestKEur(id,index))}</td>`).join("")}<td class="total-column">${keur(annual)}</td><td class="total-column ${deltaClass(annualVar)}">${delta(annualVar)}</td></tr>`; }).join("")}</tbody></table></div></section>`; }
function renderInputs(){ const index=state.inputMonth; const row=snapshot(index); const rows=driverRows(state.account,row); els.view.innerHTML=`<section class="panel"><header class="panel-head"><div><h2>${t("inputsTitle")}</h2><p>${t("inputHint")}</p></div><div class="panel-head-actions"><label>${t("month")}<select data-input-month>${[7,8,9,10,11].map((month)=>`<option value="${month}" ${index===month?"selected":""}>${yearMonthLabel(month)}</option>`).join("")}</select></label></div></header><div class="input-layout">${accountNav()}<div><div class="object-meta"><div><span>${t("account")}</span><b>${accountName(state.account)}</b></div><div><span>${t("r2Budget")}</span><b>${keur(r2KEur(state.account,index))}</b></div><div><span>${t("previous")}</span><b>${keur(previousKEur(state.account,index))}</b></div><div><span>${t("currentResult")}</span><b>${keur(latestKEur(state.account,index))}</b></div></div><div class="formula-box"><span>${t("formula")}</span><strong>${escapeHtml(formula(state.account))}</strong></div>${editableDriverPanel(state.account,row,index)}<div class="forecast-grid"><table class="driver-table" aria-label="${escapeHtml(t("inputsTitle"))}"><thead><tr><th>${t("input")}</th><th>${t("currentResult")}</th><th>${t("owner")}</th><th>${t("sourceLabel")}</th><th>${t("dataStatus")}</th></tr></thead><tbody>${rows.map(([name,value,owner,source])=>{ const saved=owner==="system"?"saved":hasSaved(owner,index)?"saved":"inherited"; return `<tr><td>${escapeHtml(name)}</td><td>${escapeHtml(value)}</td><td><span class="owner-chip">${escapeHtml(t(owner))}</span></td><td>${escapeHtml(source)}</td><td><span class="input-state ${saved}">${saved==="saved"?t("saved"):t("inherited")}</span></td></tr>`; }).join("")}</tbody></table></div></div></div></section>`; }
function renderVariance(){ const id=state.account; const bridge=annualBridge(id); const bridgeRows=[["people",t("peopleImpact")],["price",t("priceImpact")],["parameter",t("parameterImpact")],["other",t("otherImpact")]]; els.view.innerHTML=`<section class="panel"><header class="panel-head"><h2>${t("varianceTitle")}</h2>${infoTip(`${t("julyReview")} · ${t("annualReview")}`)}</header><div class="variance-layout"><div><div class="input-layout">${accountNav()}<div class="forecast-grid"><table aria-label="${escapeHtml(t("varianceTitle"))}"><thead><tr><th>${t("month")}</th><th>${t("r2Budget")}</th><th>${t("previous")}</th><th>${t("latest")}</th><th>${t("vsR2")}</th><th>${t("vsPrevious")}</th><th>${t("status")}</th></tr></thead><tbody>${Array.from({length:12},(_,index)=>index).map((index)=>{ const current=latestKEur(id,index),base=r2KEur(id,index),previous=previousKEur(id,index),actual=index<ACTUAL_CUTOFF; return `<tr class="${index===state.varianceMonth?"selected-month":""}"><td class="${actual?"month-actual":"month-forecast"}"><strong>${monthLabel(index)}</strong></td><td>${keur(base)}</td><td>${keur(previous)}</td><td>${keur(current)}</td><td class="${deltaClass(current-base)}">${delta(current-base)}</td><td class="${deltaClass(current-previous)}">${delta(current-previous)}</td><td><span class="tag ${actual?"actual":"draft"}">${actual?t("actual"):t("current")}</span></td></tr>`; }).join("")}</tbody></table></div></div></div><aside class="variance-summary"><article><span>${t("julyReview")}</span><b>${accountName(id)}</b><small>${t("actualVsR2")}: <strong class="${deltaClass(actualKEur(id,6)-r2KEur(id,6))}">${delta(actualKEur(id,6)-r2KEur(id,6))}</strong></small></article><article><span>${t("fullLatest")}</span><b>${keur(fullLatest(id))}</b><small>${t("vsR2")}: <strong class="${deltaClass(fullLatest(id)-fullR2(id))}">${delta(fullLatest(id)-fullR2(id))}</strong></small></article><article class="variance-bridge"><span>${t("varianceBridge")}</span><p>${t("bridgeHint")}</p>${bridgeRows.map(([key,label])=>`<div><span>${label}</span><strong class="${deltaClass(bridge[key])}">${delta(bridge[key])}</strong></div>`).join("")}</article><article><span>${t("formula")}</span><small>${escapeHtml(formula(id))}</small></article></aside></div></section>`; }
function departmentCard(key,info){ const confirmed=confirmationStatus(key)==="confirmed"; const control=accessRole==="adminThree"?`<button class="button ${confirmed?"":"primary"}" data-confirm="${key}" ${confirmed||state.workflow.status!=="draft"?"disabled":""}>${confirmed?t("confirmed"):t("confirm")}</button>`:""; return `<article><span class="owner-chip">${t(key)}</span><h3>${confirmed?t("confirmed"):t("pending")}</h3><p>${t(info)}</p>${control}</article>`; }
function approvalActions(){ const canApprove=accessRole==="finance"; const hasConfirmation=Object.values(state.workflow.confirmed).some(Boolean); if(state.workflow.status==="approved") return canApprove?`<button class="button danger" data-action="revokeApproval">${t("revokeApproval")}</button>`:""; if(state.workflow.status==="submitted"){ if(canApprove) return `<button class="button danger" data-action="return">${t("rejected")}</button><button class="button primary" data-action="approve">${t("approve")}</button>`; if(accessRole==="adminThree") return `<button class="button danger" data-action="withdraw">${t("withdraw")}</button>`; return `<span class="approval-wait">${escapeHtml(t("financeOnly"))}</span>`; } if(accessRole!=="adminThree") return `<span class="approval-wait">${escapeHtml(t("adminOnly"))}</span>`; return `${hasConfirmation?`<button class="button danger" data-action="withdraw">${t("withdraw")}</button>`:""}<button class="button primary" data-action="submit" ${allConfirmed()?"":"disabled"}>${t("submit")}</button>`; }
function renderApproval(){ const current=forecastStatus(); const steps=[["1",t("production"),confirmationStatus("production")==="confirmed"],["2",t("administration"),confirmationStatus("administration")==="confirmed"],["3",t("procurement"),confirmationStatus("procurement")==="confirmed"],["4",t("approval"),state.workflow.status==="submitted"||state.workflow.status==="approved"],["5",t("approved"),state.workflow.status==="approved"]]; els.view.innerHTML=`<section class="panel"><header class="panel-head"><div><h2>${t("approvalTitle")}</h2><p>${t("approvalHint")}</p></div><span class="status ${statusClass(current)}">${statusText(current)}</span></header><div class="approval-flow">${steps.map(([number,label,done],index)=>`<article class="approval-step ${done?"done":""} ${!done&&index===steps.findIndex((step)=>!step[2])?"current":""}"><span>${number}</span><b>${escapeHtml(label)}</b><p>${done?t("confirmed"):t("pending")}</p></article>`).join("")}</div><div class="approval-checklist">${departmentCard("production","productionInfo")}${departmentCard("administration","adminInfo")}${departmentCard("procurement","procurementInfo")}</div><div class="approval-actions">${approvalActions()}</div>${!allConfirmed()&&state.workflow.status==="draft"?`<p class="row-sub">${t("updateRequired")}</p>`:""}<section class="audit-log"><h3>${t("history")}</h3>${state.workflow.events.map((event)=>`<article><b>${escapeHtml(workflowEventLabel(event))}</b><p>${escapeHtml(workflowEventTime(event))}</p></article>`).join("")||`<p>${t("noHistory")}</p>`}</section></section>`; }
function renderExecution(){ els.view.innerHTML=`<section class="panel"><header class="panel-head"><div><h2>${t("executionTitle")}</h2><p>${t("executionHint")}</p></div><div class="legend"><span class="actual">${t("actual")}</span><span class="forecast">${t("forecast")}</span></div></header><div class="forecast-grid"><table class="execution-table" aria-label="${escapeHtml(t("executionTitle"))}"><thead><tr><th>${t("account")}</th><th>${t("executionFirstPeriod")}</th><th>${t("executionJuly")}</th><th>${t("executionFuture")}</th><th>${t("commitment")}</th><th>${t("sap")}</th><th>${t("available")}</th></tr></thead><tbody>${ACCOUNT_IDS.map((id)=>`<tr><td class="account-name"><b>${accountName(id)}</b><small>${accountCode(id)}</small></td><td class="month-actual">${keur(total(id,0,5,actualKEur))}</td><td class="month-actual actual-lock">${keur(actualKEur(id,6))}</td><td class="month-forecast">${keur(total(id,7,11,latestKEur))}</td><td class="pending-cell">${t("waiting")}</td><td class="pending-cell">${t("executionFuture")} · ${t("waiting")}</td><td class="pending-cell">${t("waiting")}</td></tr>`).join("")}</tbody></table></div></section>`; }
function notifyParent(){ if(query.get("embedded")!=="1") return; requestAnimationFrame(()=>window.parent.postMessage({type:"dw-three-state",height:document.documentElement.scrollHeight,view:state.view,version:state.version,navigation:t("navigation"),views:VIEW_IDS.map((id)=>({id,label:t(id)}))},window.location.origin)); }
function render(){ renderShell(); if(state.version==="r2") renderR2Baseline(); else if(state.view==="forecast") renderForecast(); else if(state.view==="inputs") renderInputs(); else if(state.view==="variance") renderVariance(); else if(state.view==="approval") renderApproval(); else if(state.view==="execution") renderExecution(); notifyParent(); }

document.addEventListener("click",(event)=>{
  const impact=event.target.closest("[data-impact-account]");
  if(impact){ state.account=impact.dataset.impactAccount; state.view="variance"; render(); return; }
  const view=event.target.closest("[data-view]");
  if(view){ state.view=view.dataset.view; render(); return; }
  const account=event.target.closest("[data-account]");
  if(account){ state.account=account.dataset.account; render(); return; }
  const saveDrivers=event.target.closest("[data-save-drivers]");
  if(saveDrivers){ saveEditableDrivers(); return; }
  const confirm=event.target.closest("[data-confirm]");
  if(confirm){
    const target=confirm.dataset.confirm;
    if(accessRole!=="adminThree"||state.workflow.status!=="draft"||!Object.hasOwn(state.workflow.confirmed,target)){ toast(t("adminOnly")); return; }
    if(state.workflow.confirmed[target]) return;
    const from=workflowStage();
    state.workflow.confirmed[target]=true;
    addWorkflowEvent("confirm",from,workflowStage(),{target});
    saveWorkflow(); render(); toast(t("confirmed")); return;
  }
  const action=event.target.closest("[data-action]");
  if(!action) return;
  const name=action.dataset.action;
  let message="";
  if(name==="submit"){
    if(accessRole!=="adminThree"){ toast(t("adminOnly")); return; }
    if(state.workflow.status!=="draft"||!allConfirmed()){ toast(t("updateRequired")); return; }
    const from=workflowStage();
    state.workflow.status="submitted";
    addWorkflowEvent("submit",from,"submitted");
    message=t("submitted");
  } else if(name==="withdraw"){
    if(accessRole!=="adminThree"||state.workflow.status==="approved"){ toast(t("adminOnly")); return; }
    if(workflowStage()==="draft") return;
    resetWorkflow("withdraw");
    message=t("withdrawn");
  } else if(name==="approve"||name==="return"||name==="revokeApproval"){
    if(accessRole!=="finance"){ toast(t("financeOnly")); return; }
    if(name==="approve"&&state.workflow.status==="submitted"){
      const from=workflowStage();
      state.workflow.status="approved";
      addWorkflowEvent("approve",from,"approved");
      message=t("approvedForecast");
    } else if(name==="return"&&state.workflow.status==="submitted"){
      resetWorkflow("return");
      message=t("rejected");
    } else if(name==="revokeApproval"&&state.workflow.status==="approved"){
      resetWorkflow("revokeApproval");
      message=t("approvalWithdrawn");
    } else return;
  } else return;
  saveWorkflow(); render(); toast(message);
});
document.addEventListener("pointerover",(event)=>{ const target=event.target.closest("[data-variance-tip]"); if(target) showVarianceHover(target); });
document.addEventListener("pointerout",(event)=>{ const target=event.target.closest("[data-variance-tip]"); if(target&&!target.contains(event.relatedTarget)) hideVarianceHover(); });
document.addEventListener("focusin",(event)=>{ const target=event.target.closest("[data-variance-tip]"); if(target) showVarianceHover(target); });
document.addEventListener("focusout",(event)=>{ if(event.target.closest("[data-variance-tip]")) hideVarianceHover(); });
window.addEventListener("scroll",hideVarianceHover,{passive:true});
window.addEventListener("resize",hideVarianceHover);
document.addEventListener("change",(event)=>{ if(event.target.matches("[data-input-month]")){ state.inputMonth=Number(event.target.value); render(); } });
els.language.addEventListener("change",()=>{ state.language=els.language.value; localStorage.setItem("dwRollingForecastLanguage",state.language); render(); });
els.version.addEventListener("change",()=>{ state.version=els.version.value; if(state.version==="r2") state.view="forecast"; render(); toast(state.version==="r2"?t("r2"):t("current")); });
window.addEventListener("message",(event)=>{ if(event.origin!==window.location.origin||event.source!==window.parent) return; if(event.data?.type==="dw-three-language"){ const language=event.data.language; if(!["zh","en","tr"].includes(language)||language===state.language) return; state.language=language; localStorage.setItem("dwRollingForecastLanguage",language); render(); return; } if(event.data?.type==="dw-three-view"){ const view=event.data.view; if(!VIEW_IDS.includes(view)||(state.version==="r2"&&view!=="forecast")||view===state.view) return; state.view=view; render(); } });
render();
